// === Tab: class ===

class arcs {

	constructor() { this.arcsArray = [] }

	//===

	tryCreateArc() {

		let kind;

		nb_A = 0; nb_R = 0;

		for ( let j = 0; j < this.arcsArray.length; j++ ) {			
			inA = this.arcsArray[j];
			if (inA.kind == "A") { nb_A += 1 } else { nb_R += 1}			
		}	

		//print ( "nb_A  " + nb_A );
		//print (	"nb_R  " + nb_R );	

		if ( random(2) < 1.0 ) { kind = "A" } else { kind = "R" }

		//===

		let angle, d_angle, rad, d_rad;

		if ( (kind == "A" && nb_A < nb_max_A ) || (kind == "R" && nb_R < nb_max_R )) {			

			angle = random (2.0, 358.0);

			if ( kind == "A" ) { d_angle = random( minD_ang, maxD_ang )
													 d_rad	 = random( minD_rad, maxD_rad);			
													 rad 		 = random( _RADIUS_2 + d_rad, _RADIUS );
												 }		

			if ( kind == "R" ) { d_angle = 1.5;
													 rad     = _RADIUS_2;
													 d_rad   = _RADIUS/4;												 	 
												  }	

			newA = new Arc ( angle, d_angle, rad, d_rad, kind );

			//===

			if ( this.arcsArray.length == 0 ) {
				this.arcsArray.push ( newA );					
			}

			for ( let i = 0; i < this.arcsArray.length; i++) {		

				inA = this.arcsArray[i];

				collide = this.check_overlaping ( inA, newA );

				if ( collide == true ) {break}											
			}

			if ( collide == false ) { this.next( newA );
																this.arcsArray.push ( newA ) }					
		}	
	}
	//===

	next (arc) {

		if ( arc.kind == "A" ) {

			arc.next_angle_0 = arc.angle_0 + step_angle;
			arc.next_angle_1 = arc.angle_1 + step_angle;

			if ( step_angle > 0.0 ) {
				arc.next_angle_0 = arc.next_angle_0 %360.0;
				arc.next_angle_1 = arc.next_angle_1 %360.0;					
			}
			else {				
				if ( arc.next_angle_0 < 0.0 ) arc.next_angle_0 += 360.0;
				if ( arc.next_angle_1 < 0.0 ) arc.next_angle_1 += 360.0;
			}	

			if ( arc.next_angle_0 < arc.next_angle_1 ) 	{ arc.next_is_above_0 = true }
			else 																				{ arc.next_is_above_0 = false}	
		}

		//===

		else {

			arc.next_rad_0 = arc.rad_0 + step_rad;
			arc.next_rad_1 = arc.rad_1 + step_rad; 	

			if ( arc.next_rad_1 < 0.0 ) arc.next_rad_1 = 0.0;			
		}																	

	}	

	//===

	check_overlaping  ( inA, newA ) {

		let inA_r0  = inA.rad_0;
		let inA_r1  = inA.rad_1;

		let newA_r0 = newA.next_rad_0;
		let newA_r1 = newA.next_rad_1;	

		if (newA_r1 > inA_r0 || newA_r0 < inA_r1) { return false } // no overlaping

		//===

		let inA_above_0  = inA.is_above_0;
		let newA_above_0 = newA.next_is_above_0;

		if ( inA_above_0 && newA_above_0 ) { return true }

		let inA_a0  = inA.angle_0;
		let inA_a1  = inA.angle_1;

		let newA_a0 = newA.next_angle_0;
		let newA_a1 = newA.next_angle_1;

		if ( inA_above_0 )  { return newA_a0 > inA_a1 || newA_a1 < inA_a0 }														 
		if ( newA_above_0 ) { return newA_a0 > inA_a1 || newA_a1 < inA_a0 }
			 										return newA_a0 > inA_a1 && newA_a1 < inA_a0;	
	}

	//=====

	update() {

		let nb_arcs = this.arcsArray.length;

		for ( let i = 0; i < nb_arcs; i++) {

			newA = this.arcsArray[i];

			//=====

			for (let m = 0; m < nb_arcs; m++) {

				if ( m != i ) {

					inA = this.arcsArray[m];
					collide = this.check_overlaping ( inA, newA );
					if ( collide == true ) break;		
				}

			}

			//=====	

			if ( collide == false ) {	

				newA.angle_0 = newA.next_angle_0;
				newA.angle_1 = newA.next_angle_1;
				newA.is_above_0 = newA.next_is_above_0;
				newA.rad_0 = newA.next_rad_0;
				newA.rad_1 = newA.next_rad_1;

				this.next(newA);				
			}					
		}		

	}
	//=====

	is_out() {	

		for (let i = 0; i < this.arcsArray.length; i++) {

			inA = this.arcsArray[i];

			if ( inA.rad_1 > _RADIUS ) {				
				this.arcsArray.splice(i,1);
				i -= 1;
			}
		}

	}

	//=====

	two_donuts () {

		ALT_Array.length = 0;
		ALB_Array.length = 0;	

		for ( let i = 0; i < this.arcsArray.length; i++ ) {

			inA = this.arcsArray[i];

			if ( !inA.is_above_0 ) {

				let a0 = inA.angle_0;

				if ( a0 > 180.0 && a0 < 360.0 )	{ ALT_Array.push(inA) }
				else 														{ ALB_Array.push(inA) }				
			}

			else {

				let arc_T = { ...inA };
				let arc_B = { ...inA };

				arc_T.angle_0 = 360.0; ALT_Array.push(arc_T); 
				arc_B.angle_1 = 0.0; ALB_Array.push(arc_B);				
			}			
		}	

		//===

		ART_Array.length = 0;

		for (let j = 0; j < ALT_Array.length; j++) {

			inA = ALT_Array[j];
			let arc_RT = { ...inA };

			let a1 = 180.0 - inA.angle_0;
			if (a1 < 0.0) a1 +=360.0;
			arc_RT.angle_1 = a1;	

			let a0 = 180.0 - inA.angle_1;
			if (a0 < 0.0) a0 +=360.0;
			arc_RT.angle_0 = a0;

			arc_RT.rad_0 = k_RADIUS - inA.rad_1;	
			arc_RT.rad_1 = k_RADIUS - inA.rad_0;

			ART_Array.push( arc_RT );				
		}

		//===

		ARB_Array.length = 0;

		for (let j = 0; j < ALB_Array.length; j++) {

			inA = ALB_Array[j];
			let arc_RB = { ...inA };

			let a1 = 180.0 - inA.angle_0;
			if (a1 < 0.0) a1 +=360.0;
			arc_RB.angle_1 = a1;	

			let a0 = 180.0 - inA.angle_1;
			if (a0 < 0.0) a0 +=360.0;
			arc_RB.angle_0 = a0;			

			arc_RB.rad_0 = k_RADIUS - inA.rad_1;	
			arc_RB.rad_1 = k_RADIUS - inA.rad_0;

			ARB_Array.push( arc_RB );				
		}		
	}

}
//=====================================================

class Arc {

	constructor ( angle, d_angle, rad, d_rad, kind ) {

		this.kind = kind;

		this.d_angle = d_angle;

		this.angle_0 = angle %360;
		this.angle_1 = (angle - d_angle);

		if (this.angle_1 < 0.0) { this.angle_1 += 360.0}

		if ( this.angle_0 < this.angle_1) { this.is_above_0 = true  }
		else															{ this.is_above_0 = false }

		//===

		this.d_rad = d_rad;

		this.rad_0 = rad;
		this.rad_1 = rad - d_rad;

		//=== next position

		this.next_angle_0 = this.angle_0;
		this.next_angle_1 = this.angle_1;
		this.next_is_above_0 = this.is_above_0;

		this.next_rad_0 = this.rad_0;
		this.next_rad_1 = this.rad_1;

		//===

		if ( kind == "A" ) { this.color = colors[0] } else { this.color = colors[1] }				
	}

}




